+import { createHmac } from "crypto";
+
+const SECRET = process.env.SESSION_SECRET || "default-secret-change-in-production";
+
+export interface SessionToken {
+  sessionId: string;
+  userId: string;
+}
+
+export const issueSessionToken = (sessionId: string, userId: string): string => {
+  const payload = JSON.stringify({ sessionId, userId });
+  const signature = createHmac("sha256", SECRET).update(payload).digest("hex");
+  return `${Buffer.from(payload).toString("base64")}.${signature}`;
+};
+
+export const verifySessionToken = (token: string): SessionToken | null => {
+  const parts = token.split(".");
+  if (parts.length !== 2) return null;
+
+  const [encodedPayload, signature] = parts;
+
+  try {
+    const payload = JSON.parse(Buffer.from(encodedPayload, "base64").toString());
+    const expectedSignature = createHmac("sha256", SECRET)
+      .update(JSON.stringify(payload))
+      .digest("hex");
+
+    if (signature !== expectedSignature) return null;
+
+    return { sessionId: payload.sessionId, userId: payload.userId };
+  } catch {
+    return null;
+  }
+};
